examples.template:
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }) {
        @OptIn(ExperimentalMonarchApi::class)
        MonarchCommentsPanel(
            threads = threads,
            filter = filter,
            onFilterChange = { filter = it },
            selectedThreadId = selected,
            onSelectedThreadChange = { selected = it /* Highlight the quoted passage in the editor. */ },
            now = {{now|millis}},
            onClose = { open = false },
            onReply = { id, body -> /* Post the reply to the server; throw on failure. */ },
            onResolvedChange = { id, resolved ->
                val index = threads.indexOfFirst { it.id == id }
                val t = threads[index]
                threads[index] = MonarchCommentsPanelThread(t.id, t.comments, t.quote, resolved = resolved)
            },
        )
    }
}

